1	import { mutation, query, QueryCtx, MutationCtx } from "./_generated/server";
2	import { v } from "convex/values";
3	import { getAuthUserId } from "@convex-dev/auth/server";
4	
5	// Bound every list read so the query stays scalable as the table grows.
6	const RESULT_LIMIT = 20;
7	
8	// Guidelines forbid `any` for ctx; use the proper context union.
9	async function requireUser(ctx: QueryCtx | MutationCtx) {
10	  const userId = await getAuthUserId(ctx);
11	  if (userId === null) {
12	    throw new Error("Not signed in");
13	  }
14	  return userId;
15	}
16	
17	export const addPerson = mutation({
18	  args: { name: v.string() },
19	  returns: v.id("people"),
20	  handler: async (ctx, args) => {
21	    const userId = await requireUser(ctx);
22	    const name = args.name.trim();
23	    if (name === "") {
24	      throw new Error("Name is required");
25	    }
26	    return await ctx.db.insert("people", {
27	      userId,
28	      name,
29	      updatedAt: Date.now(),
30	    });
31	  },
32	});
33	
34	export const searchPeople = query({
35	  args: { query: v.string() },
36	  handler: async (ctx, args) => {
37	    const userId = await requireUser(ctx);
38	    const term = args.query.trim();
39	    if (term === "") {
40	      return await ctx.db
41	        .query("people")
42	        .withIndex("by_user", (q) => q.eq("userId", userId))
43	        .order("desc")
44	        .take(RESULT_LIMIT);
45	    }
46	    return await ctx.db
47	      .query("people")
48	      .withSearchIndex("search_name", (q) =>
49	        q.search("name", term).eq("userId", userId),
50	      )
51	      .take(RESULT_LIMIT);
52	  },
53	});
54	
55	export const getPerson = query({
56	  args: { id: v.id("people") },
57	  handler: async (ctx, args) => {
58	    const userId = await requireUser(ctx);
59	    const person = await ctx.db.get("people", args.id);
60	    if (person === null || person.userId !== userId) {
61	      return null;
62	    }
63	    return person;
64	  },
65	});
